// HC-SR04 Ultrasonic Sensor Sketch
// Wiring:
// VCC -> 5V
// GND -> GND
// TRIG -> Pin 2
// ECHO -> Pin 3

const int trigPin = 2;
const int echoPin = 3;

void setup() {
  // Initialize Serial communication
  Serial.begin(9600);

  // Set pin modes
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
}

void loop() {
  // Variables for the duration of the pulse and the distance calculation
  long duration;
  float distanceCm;

  // Clear the trigPin by setting it LOW
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);

  // Set the trigPin HIGH for 10 microseconds to send a ping
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echoPin, returns the sound wave travel time in microseconds
  duration = pulseIn(echoPin, HIGH);

  // Calculate the distance in centimeters
  // Speed of sound is 340 m/s or 29 microseconds per cm
  // Divide by 2 because the sound wave travels to the object and back
  distanceCm = duration * 0.034 / 2;

  // Print the distance to the Serial Monitor
  Serial.print("Distance: ");
  Serial.print(distanceCm);
  Serial.println(" cm");

  // Wait a bit before the next measurement
  delay(500);
}

